patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..5f2bf4d
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,43 @@
+"use strict";
+// Repro for eslint/eslint#20209: no-var autofix turns a hoisted `var` into a
+// `let` that is read before its declaration (TDZ -> ReferenceError).
+// Usage: node repro/no-var-tdz.js [path-to-eslint-package]   (default: this checkout)
+const path = require("node:path");
+const pkgDir = path.resolve(process.argv[2] || path.join(__dirname, ".."));
+const { Linter } = require(path.join(pkgDir, "lib/api"));
+const version = require(path.join(pkgDir, "package.json")).version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+
+const linter = new Linter({ configType: "flat" });
+const { output, messages, fixed } = linter.verifyAndFix(
+	code,
+	[{ rules: { "no-var": "error" } }],
+	{ filename: "x.js" },
+);
+
+console.log(`eslint ${version}`);
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId})`));
+console.log(`fixed: ${fixed}\n--- output ---\n${output}\n--------------`);
+
+// Run the fixed output to see whether it throws.
+const body = output.replace(/^export /u, "");
+let runtime;
+try {
+	new Function(`${body}; return a();`)();
+	runtime = "runs without error";
+} catch (e) {
+	runtime = `${e.name}: ${e.message}`;
+}
+console.log("running fixed code:", runtime);
+
+if (fixed && /\blet o\b/u.test(output) && runtime.startsWith("ReferenceError")) {
+	console.log("BUG REPRODUCED: no-var autofix produced code that throws a ReferenceError");
+	process.exitCode = 1;
+} else {
+	console.log("not reproduced: autofix did not introduce a TDZ ReferenceError");
+}
